sysauto_script.script:
(function() {
    var today = new GlideDateTime();
    today.addDaysUTC(-180);
    var cutoffDate = today.getDate().toString();

    var gr = new GlideRecord('x_848842_techdesk_asset');
    gr.addQuery('lifecycle_state', 'deployed');
    gr.addQuery('last_audit_date', '<', cutoffDate);
    gr.query();

    var count = gr.getRowCount();
    gs.info('TechDesk Overdue Audit Alert: Found ' + count + ' assets with audits overdue by more than 180 days');
})();
